    col(COL.primary); mgraphics.set_line_width(1.4);
    for (i = 0; i <= 30; i++) { var tt = i / 30, yy = cy + r * 0.6 - (r * 1.2) * Math.exp(-tt * (2 + 10 * v)); if (i === 0) mgraphics.move_to(cx - r * 0.7 + tt * r * 1.4, yy); else mgraphics.line_to(cx - r * 0.7 + tt * r * 1.4, yy); }
